import { styled } from '@hexa-ui/theme';

export const StyledHowWeDoItCardRoot = styled('div', {
  width: '100%',
  minWidth: 0,
  boxSizing: 'border-box',
  height: '100%',
  minHeight: 0,
  display: 'flex',
  flexDirection: 'column',

  '& [data-testid="sub-pillar-card"]': {
    flex: 1,
    minHeight: 0,
    width: '100%',
    maxWidth: 'none',
    height: '100%',
    display: 'flex',
    flexDirection: 'column',
  },

  '& [data-testid="sub-pillar-card-content"]': {
    flex: 1,
    minHeight: 0,
    display: 'flex',
    flexDirection: 'column',
  },

  [`& .innovation-home-how-we-do-it-big-number.bigNumberCard`]: {
    backgroundColor: 'transparent',
  },

  [`& .innovation-home-how-we-do-it-big-number.bigNumberContainer`]: {
    flex: 1,
    justifyContent: 'space-between',
    height: 'auto !important',

    '& > [class*="-orientation-vertical"]': {
      height: 'auto !important',
    },
  },

  variants: {
    interactive: {
      true: {
        '& [data-testid="sub-pillar-card"]': {
          cursor: 'pointer',
          transition:
            'background-color 300ms ease-out, box-shadow 300ms ease-out',

          '&:hover': {
            background:
              'linear-gradient(0deg, rgba(229, 182, 17, 0.04) 0%, rgba(229, 182, 17, 0.04) 100%), #FFF',
            boxShadow: '0 0 8px 0 rgba(0, 0, 0, 0.16)',
          },
        },
      },
      false: {},
    },
  },

  defaultVariants: {
    interactive: false,
  },
});
